class Solution {
  public int xorRegisterPositiveInkInvoice(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int state=0;for(int x:a){state^=x;out.add(state);}}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
